import React, { useState, useEffect, useCallback } from 'react';
import {
  LineChart, Line, BarChart, Bar, XAxis, YAxis,
  CartesianGrid, Tooltip, Legend, ResponsiveContainer, Cell,
} from 'recharts';
import api from '../api/axios';
import './WorldPopulation.css';

const TABS      = ['Gender', 'Age Group', 'Growth Rate'];
const GENDERS   = ['All', 'Both', 'Male', 'Female'];
const AGE_COLS  = [
  { key: 'age_0_4',      label: '0–4' },
  { key: 'age_5_9',      label: '5–9' },
  { key: 'age_10_14',    label: '10–14' },
  { key: 'age_15_19',    label: '15–19' },
  { key: 'age_20_24',    label: '20–24' },
  { key: 'age_25_29',    label: '25–29' },
  { key: 'age_30_34',    label: '30–34' },
  { key: 'age_35_39',    label: '35–39' },
  { key: 'age_40_44',    label: '40–44' },
  { key: 'age_45_49',    label: '45–49' },
  { key: 'age_50_54',    label: '50–54' },
  { key: 'age_55_59',    label: '55–59' },
  { key: 'age_60_64',    label: '60–64' },
  { key: 'age_65_69',    label: '65–69' },
  { key: 'age_70_74',    label: '70–74' },
  { key: 'age_75_79',    label: '75–79' },
  { key: 'age_80_84',    label: '80–84' },
  { key: 'age_85_89',    label: '85–89' },
  { key: 'age_90_94',    label: '90–94' },
  { key: 'age_95_99',    label: '95–99' },
  { key: 'age_100_plus', label: '100+' },
];

const CHART_COLORS = ['#0d6e6e', '#1b74e4', '#f59e0b', '#10b981', '#8b5cf6', '#ef4444'];

export default function WorldPopulation() {
  const [activeTab, setActiveTab] = useState('Gender');
  const [viewMode,  setViewMode]  = useState('table');

  // Filter options
  const [countries, setCountries] = useState([]);
  const [regions,   setRegions]   = useState([]);
  const [years,     setYears]     = useState([]);

  // Selected filters
  const [selCountry, setSelCountry] = useState('Global');
  const [selRegion,  setSelRegion]  = useState('');
  const [selGender,  setSelGender]  = useState('All');
  const [selYear,    setSelYear]    = useState('2024');
  const [yearFrom,   setYearFrom]   = useState(2024);
  const [yearTo,     setYearTo]     = useState(2050);

  // Data
  const [genderData, setGenderData] = useState([]);
  const [ageData,    setAgeData]    = useState([]);
  const [growthData, setGrowthData] = useState([]);
  const [loading,    setLoading]    = useState(false);
  const [error,      setError]      = useState('');

  // Load filter options
  useEffect(() => {
    api.get('/population/filter-options')
      .then(r => {
        setCountries(r.data.countries || []);
        setRegions(r.data.regions || []);
        setYears(r.data.years || []);
      })
      .catch(() => {});
  }, []);

  // Fetch data
  const fetchData = useCallback(async () => {
    setLoading(true); setError('');
    const params = new URLSearchParams();
    if (selCountry) params.set('country', selCountry);
    if (selRegion)  params.set('region',  selRegion);
    if (selGender && selGender !== 'All') params.set('gender', selGender);
    params.set('year_from', yearFrom);
    params.set('year_to',   yearTo);

    const ageParams = new URLSearchParams();
    if (selCountry) ageParams.set('country', selCountry);
    if (selRegion)  ageParams.set('region',  selRegion);
    if (selGender && selGender !== 'All') ageParams.set('gender', selGender);
    ageParams.set('year', selYear);

    try {
      const [genderRes, ageRes, growthRes] = await Promise.all([
        api.get(`/population/gender?${params}`),
        api.get(`/population/age?${ageParams}`),
        api.get(`/population/growth?${params}`),
      ]);
      setGenderData(genderRes.data);
      setAgeData(ageRes.data);
      setGrowthData(growthRes.data);
    } catch {
      setError('Failed to load population data.');
    } finally {
      setLoading(false);
    }
  }, [selCountry, selRegion, selGender, selYear, yearFrom, yearTo]);

  useEffect(() => { fetchData(); }, [fetchData]);

  // Build age chart data from first row
  const ageChartData = ageData.slice(0, 1).flatMap(row =>
    AGE_COLS.map(col => ({
      age:   col.label,
      value: parseFloat(row[col.key] || 0),
    }))
  );

  const handleExport = () => {
    let rows = [], headers = [];
    if (activeTab === 'Gender') {
      headers = ['Country', 'Region', 'Year', 'Gender', 'Cases', 'Growth Rate'];
      rows = genderData.map(r => [r.country, r.region, r.year, r.gender, r.cases, r.growth_rate]);
    } else if (activeTab === 'Age Group') {
      headers = ['Country', 'Region', 'Year', 'Gender', ...AGE_COLS.map(c => c.label)];
      rows = ageData.map(r => [r.country, r.region, r.year, r.gender, ...AGE_COLS.map(c => r[c.key])]);
    } else {
      headers = ['Country', 'Region', 'Year', 'Gender', 'Growth Rate'];
      rows = growthData.map(r => [r.country, r.region, r.year, r.gender, r.growth_rate]);
    }
    const csv = [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
    const a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
    a.download = `population_${activeTab.replace(' ', '_')}_export.csv`;
    a.click();
  };

  return (
    <div className="wp-page">

      {/* ── Controls ──────────────────────────────────────── */}
      <div className="wp-controls">
        <div className="wp-tabs">
          {TABS.map(tab => (
            <button
              key={tab}
              className={`wp-tab${activeTab === tab ? ' active' : ''}`}
              onClick={() => setActiveTab(tab)}
            >
              {tab}
            </button>
          ))}
        </div>

        {/* Year range slider — hidden for Age Group tab */}
        {activeTab !== 'Age Group' && (
          <div className="wp-year-range">
            <span className="year-clean-label">Year range</span>
            <div className="year-clean-row">
              <span className="year-arrow">←</span>
              <div
                className="year-track"
                style={{
                  background: `linear-gradient(to right,
                    #d0d8e4 0%,
                    #d0d8e4 ${((yearFrom - 2024) / (2100 - 2024)) * 100}%,
                    var(--blue-accent) ${((yearFrom - 2024) / (2100 - 2024)) * 100}%,
                    var(--blue-accent) ${((yearTo - 2024) / (2100 - 2024)) * 100}%,
                    #d0d8e4 ${((yearTo - 2024) / (2100 - 2024)) * 100}%,
                    #d0d8e4 100%)`
                }}
              >
                <input type="range" min={2024} max={yearTo}   value={yearFrom}
                  onChange={e => setYearFrom(+e.target.value)} />
                <input type="range" min={yearFrom} max={2100} value={yearTo}
                  onChange={e => setYearTo(+e.target.value)} />
              </div>
              <span className="year-arrow">→</span>
            </div>
            <div className="year-clean-nums">
              <span>{yearFrom}</span>
              <span>{yearTo}</span>
            </div>
          </div>
        )}

        <div className="wp-actions">
          <button className="btn-dl" onClick={handleExport}>⬇ Download</button>
          <button className="btn-save">Save report</button>
        </div>
      </div>

      <div className="wp-body">
        {/* ── Sidebar ───────────────────────────────────────── */}
        <aside className="wp-sidebar">
          <h3 className="sidebar-title">Selections</h3>

          <label className="fl">Region</label>
          <select className="fs" value={selRegion} onChange={e => setSelRegion(e.target.value)}>
            <option value="">All regions</option>
            {regions.map(r => <option key={r} value={r}>{r}</option>)}
          </select>

          <label className="fl">Country</label>
          <select className="fs" value={selCountry} onChange={e => setSelCountry(e.target.value)}>
            <option value="">All countries</option>
            {countries.map(c => <option key={c} value={c}>{c}</option>)}
          </select>

          <label className="fl">Gender</label>
          <select className="fs" value={selGender} onChange={e => setSelGender(e.target.value)}>
            {GENDERS.map(g => <option key={g} value={g}>{g}</option>)}
          </select>

          {activeTab === 'Age Group' && (
            <>
              <label className="fl">Year</label>
              <select className="fs" value={selYear} onChange={e => setSelYear(e.target.value)}>
                {years.map(y => <option key={y} value={y}>{y}</option>)}
              </select>
            </>
          )}

          <div className="sidebar-count">
            {loading ? '…' : activeTab === 'Gender'
              ? `${genderData.length} records`
              : activeTab === 'Age Group'
              ? `${ageData.length} records`
              : `${growthData.length} records`
            }
          </div>
        </aside>

        {/* ── Main ──────────────────────────────────────────── */}
        <div className="wp-main">
          <div className="view-toggle">
            <button className={`tb${viewMode === 'table' ? ' active' : ''}`} onClick={() => setViewMode('table')}>Table</button>
            <button className={`tb${viewMode === 'chart' ? ' active' : ''}`} onClick={() => setViewMode('chart')}>Chart</button>
          </div>

          {error && <div className="prev-error">{error}</div>}

          {loading ? (
            <div className="prev-loading"><div className="spinner" />Loading data…</div>
          ) : viewMode === 'table' ? (

            /* ── TABLE VIEWS ──────────────────────────────────── */
            <div className="table-wrapper">
              {activeTab === 'Gender' && (
                <table className="data-table">
                  <thead>
                    <tr>
                      <th>Country</th>
                      <th>Region</th>
                      <th>Sub-region</th>
                      <th>Type</th>
                      <th>Year</th>
                      <th>Gender</th>
                      <th>Cases (thousands)</th>
                      <th>Growth Rate (%)</th>
                    </tr>
                  </thead>
                  <tbody>
                    {genderData.length === 0 ? (
                      <tr><td colSpan={8} className="no-data">No data for selected filters.</td></tr>
                    ) : genderData.map((row, i) => (
                      <tr key={i}>
                        <td className="country-cell">{row.country}</td>
                        <td>{row.region}</td>
                        <td>{row.sub_region}</td>
                        <td>{row.type}</td>
                        <td>{row.year}</td>
                        <td>{row.gender}</td>
                        <td className="value-cell">{Number(row.cases).toLocaleString()}</td>
                        <td className={`value-cell ${row.growth_rate < 0 ? 'negative' : ''}`}>
                          {row.growth_rate}%
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}

              {activeTab === 'Age Group' && (
                <table className="data-table">
                  <thead>
                    <tr>
                      <th>Country</th>
                      <th>Region</th>
                      <th>Year</th>
                      <th>Gender</th>
                      {AGE_COLS.map(c => <th key={c.key}>{c.label}</th>)}
                    </tr>
                  </thead>
                  <tbody>
                    {ageData.length === 0 ? (
                      <tr><td colSpan={25} className="no-data">No data for selected filters.</td></tr>
                    ) : ageData.map((row, i) => (
                      <tr key={i}>
                        <td className="country-cell">{row.country}</td>
                        <td>{row.region}</td>
                        <td>{row.year}</td>
                        <td>{row.gender}</td>
                        {AGE_COLS.map(c => (
                          <td key={c.key} className="value-cell">
                            {Number(row[c.key] || 0).toLocaleString(undefined, { maximumFractionDigits: 0 })}
                          </td>
                        ))}
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}

              {activeTab === 'Growth Rate' && (
                <table className="data-table">
                  <thead>
                    <tr>
                      <th>Country</th>
                      <th>Region</th>
                      <th>Sub-region</th>
                      <th>Type</th>
                      <th>Year</th>
                      <th>Gender</th>
                      <th>Growth Rate (%)</th>
                    </tr>
                  </thead>
                  <tbody>
                    {growthData.length === 0 ? (
                      <tr><td colSpan={7} className="no-data">No data for selected filters.</td></tr>
                    ) : growthData.map((row, i) => (
                      <tr key={i}>
                        <td className="country-cell">{row.country}</td>
                        <td>{row.region}</td>
                        <td>{row.sub_region}</td>
                        <td>{row.type}</td>
                        <td>{row.year}</td>
                        <td>{row.gender}</td>
                        <td className={`value-cell ${row.growth_rate < 0 ? 'negative' : ''}`}>
                          {row.growth_rate}%
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>

          ) : (
            /* ── CHART VIEWS ──────────────────────────────────── */
            <div className="chart-wrapper">
              {activeTab === 'Gender' && (
                <>
                  <h3 className="chart-title">Population Cases Over Time — {selCountry || 'Global'}</h3>
                  <ResponsiveContainer width="100%" height={350}>
                    <LineChart data={genderData} margin={{ left: 20, right: 30, top: 10, bottom: 10 }}>
                      <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                      <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                      <YAxis tick={{ fontSize: 11 }} tickFormatter={v => (v / 1000).toFixed(0) + 'M'} />
                      <Tooltip formatter={v => [Number(v).toLocaleString(), 'Cases (thousands)']} />
                      <Legend />
                      <Line type="monotone" dataKey="cases" stroke="#0d6e6e" strokeWidth={2} dot={false} name="Population" />
                    </LineChart>
                  </ResponsiveContainer>
                </>
              )}

              {activeTab === 'Age Group' && (
                <>
                  <h3 className="chart-title">Population by Age Group — {selCountry || 'Global'} ({selYear})</h3>
                  <ResponsiveContainer width="100%" height={350}>
                    <BarChart data={ageChartData} margin={{ left: 20, right: 30, top: 10, bottom: 10 }}>
                      <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                      <XAxis dataKey="age" tick={{ fontSize: 10 }} />
                      <YAxis tick={{ fontSize: 11 }} tickFormatter={v => (v / 1000).toFixed(0) + 'K'} />
                      <Tooltip formatter={v => [Number(v).toLocaleString(), 'Population (thousands)']} />
                      <Bar dataKey="value" radius={[4, 4, 0, 0]}>
                        {ageChartData.map((_, i) => (
                          <Cell key={i} fill={CHART_COLORS[i % CHART_COLORS.length]} />
                        ))}
                      </Bar>
                    </BarChart>
                  </ResponsiveContainer>
                </>
              )}

              {activeTab === 'Growth Rate' && (
                <>
                  <h3 className="chart-title">Population Growth Rate Over Time — {selCountry || 'Global'}</h3>
                  <ResponsiveContainer width="100%" height={350}>
                    <LineChart data={growthData} margin={{ left: 20, right: 30, top: 10, bottom: 10 }}>
                      <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                      <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                      <YAxis tick={{ fontSize: 11 }} tickFormatter={v => v + '%'} />
                      <Tooltip formatter={v => [v + '%', 'Growth Rate']} />
                      <Legend />
                      <Line type="monotone" dataKey="growth_rate" stroke="#1b74e4" strokeWidth={2} dot={false} name="Growth Rate %" />
                    </LineChart>
                  </ResponsiveContainer>
                  <p className="chart-note"><em>Negative values indicate population decline</em></p>
                </>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
